from fastapi import FastAPI, Query, Header, Cookie
from fastapi.testclient import TestClient
from pydantic import BaseModel, Field
import pytest

app = FastAPI()

class QueryModel(BaseModel):
    q: str = Field(..., alias="query-param")

@app.get("/query")
async def read_query(params: QueryModel = Query()):
    return params

class HeaderModel(BaseModel):
    h: str = Field(..., alias="header-param")

@app.get("/header")
async def read_header(params: HeaderModel = Header()):
    return params

client = TestClient(app)

def test_query_alias():
    # Issue 1: Value extracted by alias, but put into values with field.name
    response = client.get("/query?query-param=foo")
    print(f"Query Response: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"q": "foo"}

def test_query_alias_error():
    # Issue 2: Pass by name, should be validation error and 'q' should be in input
    response = client.get("/query?q=foo")
    print(f"Query Error Response: {response.json()}")
    assert response.status_code == 422
    # Check if 'q' is in the input of the error
    # The error structure for Pydantic v2 is different from v1.
    # Let's just print it and see.
    assert any("q" in str(detail) for detail in response.json()["detail"])

def test_header_alias():
    response = client.get("/header", headers={"header-param": "foo"})
    print(f"Header Response: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"h": "foo"}

def test_header_alias_error():
    response = client.get("/header", headers={"h": "foo"})
    print(f"Header Error Response: {response.json()}")
    assert response.status_code == 422
    assert any("h" in str(detail) for detail in response.json()["detail"])

if __name__ == "__main__":
    try:
        test_query_alias()
        print("test_query_alias passed")
    except Exception as e:
        print(f"test_query_alias failed: {e}")

    try:
        test_query_alias_error()
        print("test_query_alias_error passed")
    except Exception as e:
        print(f"test_query_alias_error failed: {e}")

    try:
        test_header_alias()
        print("test_header_alias passed")
    except Exception as e:
        print(f"test_header_alias failed: {e}")

    try:
        test_header_alias_error()
        print("test_header_alias_error passed")
    except Exception as e:
        print(f"test_header_alias_error failed: {e}")

